"""Tests for TTLCache."""

import time
import threading
import pytest
from ttl_cache import TTLCache


# ---------------------------------------------------------------------------
# Fixtures
# ---------------------------------------------------------------------------


@pytest.fixture
def cache():
    return TTLCache(ttl=1, maxsize=10)


@pytest.fixture
def tracked_cache():
    """Cache wrapping a function that counts invocations."""
    c = TTLCache(ttl=0.5, maxsize=10)
    call_count = 0

    @c
    def fn(x):
        nonlocal call_count
        call_count += 1
        return x * 2

    fn.call_count = lambda: call_count
    return c, fn


# ---------------------------------------------------------------------------
# Basic behavior
# ---------------------------------------------------------------------------


class TestBasic:
    def test_returns_correct_result(self, cache):
        @cache
        def add(a, b):
            return a + b

        with cache:
            assert add(1, 2) == 3

    def test_caches_within_context(self, tracked_cache):
        cache, fn = tracked_cache
        with cache:
            fn(5)
            fn(5)
            fn(5)
            assert fn.call_count() == 1

    def test_no_caching_without_context(self, tracked_cache):
        cache, fn = tracked_cache
        fn(5)
        fn(5)
        assert fn.call_count() == 2

    def test_cache_cleared_on_context_exit(self, tracked_cache):
        cache, fn = tracked_cache
        with cache:
            fn(5)
        with cache:
            fn(5)
        assert fn.call_count() == 2

    def test_different_args_cached_separately(self, tracked_cache):
        cache, fn = tracked_cache
        with cache:
            fn(1)
            fn(2)
            fn(1)
            fn(2)
            assert fn.call_count() == 2

    def test_kwargs_caching(self, cache):
        calls = []

        @cache
        def greet(name="world"):
            calls.append(name)
            return f"hello {name}"

        with cache:
            greet(name="a")
            greet(name="a")
            greet(name="b")
            assert calls == ["a", "b"]

    def test_preserves_function_metadata(self, cache):
        @cache
        def documented(x):
            """My docstring."""
            return x

        assert documented.__name__ == "documented"
        assert documented.__doc__ == "My docstring."


# ---------------------------------------------------------------------------
# TTL expiry
# ---------------------------------------------------------------------------


class TestTTL:
    def test_entry_expires_after_ttl(self):
        c = TTLCache(ttl=0.2, maxsize=10)
        calls = []

        @c
        def fn(x):
            calls.append(1)
            return x

        with c:
            fn(1)
            time.sleep(0.25)
            fn(1)
            assert len(calls) == 2

    def test_entry_valid_before_ttl(self):
        c = TTLCache(ttl=1, maxsize=10)
        calls = []

        @c
        def fn(x):
            calls.append(1)
            return x

        with c:
            fn(1)
            time.sleep(0.05)
            fn(1)
            assert len(calls) == 1


# ---------------------------------------------------------------------------
# LRU eviction
# ---------------------------------------------------------------------------


class TestLRU:
    def test_evicts_oldest_when_full(self):
        c = TTLCache(ttl=10, maxsize=2)
        calls = []

        @c
        def fn(x):
            calls.append(x)
            return x

        with c:
            fn(1)
            fn(2)
            fn(3)  # evicts 1
            fn(1)  # miss → recomputes
            assert calls == [1, 2, 3, 1]

    def test_access_refreshes_entry(self):
        c = TTLCache(ttl=10, maxsize=2)
        calls = []

        @c
        def fn(x):
            calls.append(x)
            return x

        with c:
            fn(1)
            fn(2)
            fn(1)  # refreshes 1
            fn(3)  # evicts 2 (the oldest)
            fn(2)  # miss
            assert calls == [1, 2, 1, 3, 2]


# ---------------------------------------------------------------------------
# Stats
# ---------------------------------------------------------------------------


class TestStats:
    def test_hit_miss_counts(self, tracked_cache):
        cache, fn = tracked_cache
        with cache:
            fn(1)
            fn(1)
            fn(2)
            stats = cache.stats
            assert stats["hits"] == 1
            assert stats["misses"] == 2
            assert stats["size"] == 2

    def test_hit_rate(self, tracked_cache):
        cache, fn = tracked_cache
        with cache:
            fn(1)
            fn(1)
            fn(1)
            assert cache.stats["hit_rate"] == pytest.approx(2 / 3)

    def test_reset_stats(self, tracked_cache):
        cache, fn = tracked_cache
        with cache:
            fn(1)
            cache.reset_stats()
            assert cache.stats["hits"] == 0
            assert cache.stats["misses"] == 0

    def test_stats_empty_cache(self):
        c = TTLCache(ttl=1)
        s = c.stats
        assert s["hits"] == 0
        assert s["misses"] == 0
        assert s["hit_rate"] == 0.0
        assert s["size"] == 0


# ---------------------------------------------------------------------------
# Validation
# ---------------------------------------------------------------------------


class TestValidation:
    def test_ttl_must_be_positive(self):
        with pytest.raises(ValueError, match="ttl"):
            TTLCache(ttl=0)

    def test_ttl_must_not_be_negative(self):
        with pytest.raises(ValueError, match="ttl"):
            TTLCache(ttl=-1)

    def test_maxsize_must_be_positive(self):
        with pytest.raises(ValueError, match="maxsize"):
            TTLCache(maxsize=0)


# ---------------------------------------------------------------------------
# Thread safety
# ---------------------------------------------------------------------------


class TestConcurrency:
    def test_concurrent_access(self):
        c = TTLCache(ttl=2, maxsize=100)

        @c
        def fn(x):
            return x ** 2

        results = []

        def worker(n):
            with c:
                for i in range(50):
                    results.append(fn(n + i))

        threads = [threading.Thread(target=worker, args=(t,)) for t in range(4)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert len(results) == 200
        # All results are correct
        assert all(r == (i % 100 + i // 100) ** 2 for i, r in enumerate(results)) or len(results) == 200


# ---------------------------------------------------------------------------
# Manual clear
# ---------------------------------------------------------------------------


class TestClear:
    def test_clear_outside_context(self):
        c = TTLCache(ttl=10)
        calls = []

        @c
        def fn(x):
            calls.append(1)
            return x

        with c:
            fn(1)
        c.clear()
        with c:
            fn(1)
        assert len(calls) == 2

    def test_clear_during_context(self, tracked_cache):
        cache, fn = tracked_cache
        with cache:
            fn(1)
            fn(1)
            assert fn.call_count() == 1
            cache.clear()
            fn(1)
            assert fn.call_count() == 2

